import React from "react";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";

const Cart = () => {
    const { cart, addToCart, removeFromCart, updateQuantity, setOrders } = useCart();
    const navigate = useNavigate();

    // Handle placing the order
    const handlePlaceOrder = () => {
        const order = {
            id: new Date().getTime(), // Generate unique order ID
            items: cart,
            date: new Date().toLocaleDateString(),
        };
        setOrders((prevOrders) => [...prevOrders, order]); // Add order to orders state
        setCart([]); // Clear cart after placing the order
        alert("Đặt hàng thành công!");
        navigate("/orderlist"); // Navigate to the order list page
    };

    return (
        <div className="container my-5">
            <h2>Giỏ Hàng</h2>
            {cart.length === 0 ? (
                <p>Giỏ hàng của bạn trống.</p>
            ) : (
                <div className="row">
                    <div className="col-md-8">
                        {cart.map((product) => (
                            <div key={product.id} className="d-flex align-items-center mb-3">
                                <img src={product.image} alt={product.name} className="product-image" style={{ width: "100px", height: "100px" }} />
                                <div className="ms-3">
                                    <h5>{product.name}</h5>
                                    <p>{product.description}</p>
                                    <div className="d-flex">
                                        <button
                                            className="btn btn-secondary"
                                            onClick={() => updateQuantity(product.id, "decrease")}
                                        >
                                            -
                                        </button>
                                        <span className="mx-2">{product.quantity}</span>
                                        <button
                                            className="btn btn-secondary"
                                            onClick={() => updateQuantity(product.id, "increase")}
                                        >
                                            +
                                        </button>
                                    </div>
                                    <p className="mt-2">Giá: {product.price} VND</p>
                                </div>
                                <button
                                    className="btn btn-danger ms-3"
                                    onClick={() => removeFromCart(product.id)}
                                >
                                    Xóa
                                </button>
                            </div>
                        ))}
                    </div>

                    <div className="col-md-4">
                        <div className="p-3 border rounded">
                            <h3>Thông Tin Thanh Toán</h3>
                            <p>Tổng Số Lượng: {cart.reduce((total, item) => total + item.quantity, 0)}</p>
                            <p>Tổng Tiền: {cart.reduce((total, item) => total + item.price * item.quantity, 0)} VND</p>
                            <button className="btn btn-success w-100" onClick={handlePlaceOrder}>
                                Thanh Toán
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Cart;
